import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 25 章 内置技能库（二）：文档、表格与演示（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第25章 内置技能库（二）：文档、表格与演示（易懂版）.md","filePath":"easy/第25章 内置技能库（二）：文档、表格与演示（易懂版）.md"}'),d={name:"easy/第25章 内置技能库（二）：文档、表格与演示（易懂版）.md"};function n(s,t,l,i,h,_){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-25-章-内置技能库-二-文档、表格与演示-易懂版" tabindex="-1">第 25 章 内置技能库（二）：文档、表格与演示（易懂版） <a class="header-anchor" href="#第-25-章-内置技能库-二-文档、表格与演示-易懂版" aria-label="Permalink to &quot;第 25 章 内置技能库（二）：文档、表格与演示（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 <a href="./../bluebook/第五篇 平台能力全景/第 25 章 内置技能库（二）：文档、表格与演示.html">第 25 章 内置技能库（二）：文档、表格与演示（完整版）</a>。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>你要交出去的东西，不再只是文字——Word、Excel、PPT、PDF，我都能做成能直接打开的文件。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>以前我给你&quot;一碗菜&quot;（聊天里的文字），你还得自己装盘。 现在我能直接给你<strong>装好盘的礼盒</strong>：Word 文档、Excel 表格、PPT 演示稿、PDF 定稿。</p><p>区别在于：<strong>能直接交出去，不用你再复制粘贴一遍。</strong></p><h2 id="三个-家庭-按你要交的东西挑" tabindex="-1">三个&quot;家庭&quot;（按你要交的东西挑） <a class="header-anchor" href="#三个-家庭-按你要交的东西挑" aria-label="Permalink to &quot;三个&quot;家庭&quot;（按你要交的东西挑）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你要交什么</th><th>用哪个</th><th>典型用途</th></tr></thead><tbody><tr><td><strong>文档</strong>（Word）</td><td>文档技能</td><td>报告、方案、合同、白皮书</td></tr><tr><td><strong>表格</strong>（Excel）</td><td>表格技能</td><td>台账、预算、数据清洗、图表</td></tr><tr><td><strong>演示</strong>（PPT）</td><td>演示技能</td><td>汇报、路演、培训课件</td></tr><tr><td><strong>PDF / 流程图</strong></td><td>PDF、Mermaid 技能</td><td>定稿输出、流程与架构图</td></tr></tbody></table><h2 id="关键规矩-先大纲-后成稿" tabindex="-1">关键规矩：先大纲，后成稿 <a class="header-anchor" href="#关键规矩-先大纲-后成稿" aria-label="Permalink to &quot;关键规矩：先大纲，后成稿&quot;">​</a></h2><p><strong>别一上来就要成品。</strong> 先让我出大纲或目录，你看完点头，我再生成文件。</p><p>这样最省时间——<strong>改大纲只要一分钟，改一份 40 页 PPT 要半小时。</strong></p><h2 id="一句好用的口令" tabindex="-1">一句好用的口令 <a class="header-anchor" href="#一句好用的口令" aria-label="Permalink to &quot;一句好用的口令&quot;">​</a></h2><blockquote><p>&quot;请交付一份【Word/Excel/PPT】：内容来自【文件/前面的分析】，结构是【章节或工作表】，格式按【模板/配色/页数】，<strong>先给我大纲确认，再生成文件</strong>；生成后自检能打开、无乱码、数字对得上。&quot;</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 直接要成品——<strong>先要大纲，省一半返工</strong>；</li><li>❌ 不给模板还期望&quot;跟公司样式一样&quot;——<strong>有模板就给模板</strong>；</li><li>❌ 生成完不看——<strong>打开检查一遍：数字、页码、字体</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>交付级产出 = 先说清要交什么 + 先确认大纲 + 生成后自检。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>想一下你这周要交的东西——<strong>它最终长什么样？Word、Excel 还是 PPT？</strong> 想清楚形状，指令就好写了。</p><p>👉 [下一章：专家助手库，11 位内置专家与自定义（易懂版）](第26章 专家助手库：11 位内置专家与自定义（易懂版）.md)</p>',21)])])}const p=a(d,[["render",n]]);export{u as __pageData,p as default};
